{
  "title": "A slower Kyoto day",
  "summary": "Two temples, two long meals, and a lot less rushing between them.",
  "stops": [
    {
      "poi_id": "p2",
      "kind": "activity",
      "must_do_id": "m2",
      "note": "The golden one stays. Shoes off, phone down, eyes up."
    },
    {
      "poi_id": "p16",
      "kind": "meal",
      "must_do_id": null,
      "note": "A long, quiet kaiseki (multi-course Kyoto meal) lunch that suits the vegetarians and the slower pace."
    },
    {
      "poi_id": "p12",
      "kind": "activity",
      "must_do_id": null,
      "note": "One more temple, then we stop pretending to be efficient."
    },
    {
      "poi_id": "p19",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner with proper vegetarian choices, because the crew eats better than the deer."
    }
  ]
